/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bookings` (
  `booking_id` binary(16) NOT NULL,
  `booking_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `start_time` datetime NOT NULL,
  `end_time` datetime NOT NULL,
  `actual_checkin_time` datetime DEFAULT NULL,
  `actual_checkout_time` datetime DEFAULT NULL,
  `salon_id` binary(16) NOT NULL,
  `user_id` binary(16) NOT NULL,
  `stylist_id` binary(16) NOT NULL,
  `customer_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `subtotal_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `discount_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `voucher_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loyalty_points_used` int NOT NULL DEFAULT '0',
  `loyalty_points_discount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `total_amount` decimal(15,2) DEFAULT NULL,
  `payment_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UNPAID',
  `payment_method` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CASH',
  `seat_chair_number` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cancellation_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cancelled_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `customer_notes` text COLLATE utf8mb4_unicode_ci,
  `stylist_notes` text COLLATE utf8mb4_unicode_ci,
  `is_reviewed` tinyint(1) NOT NULL DEFAULT '0',
  `booking_source` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'WEB',
  `version` bigint DEFAULT '0',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`booking_id`),
  KEY `idx_bookings_user_status` (`user_id`,`status`,`is_deleted`),
  KEY `idx_bookings_stylist_status` (`stylist_id`,`status`,`is_deleted`),
  KEY `idx_bookings_stylist_schedule` (`stylist_id`,`start_time`,`end_time`,`status`,`is_deleted`),
  KEY `idx_bookings_salon_timeline` (`salon_id`,`start_time`,`status`),
  KEY `idx_bookings_stylist_schedule_v2` (`stylist_id`,`status`,`start_time`,`end_time`),
  CONSTRAINT `fk_bookings_salon` FOREIGN KEY (`salon_id`) REFERENCES `salons` (`salon_id`),
  CONSTRAINT `fk_bookings_stylist` FOREIGN KEY (`stylist_id`) REFERENCES `stylists` (`stylist_id`),
  CONSTRAINT `fk_bookings_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

