--
-- Table structure for table `reviews`
--

DROP TABLE IF EXISTS `reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reviews` (
  `review_id` binary(16) NOT NULL,
  `user_id` binary(16) NOT NULL,
  `review_target_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SERVICE',
  `product_id` binary(16) DEFAULT NULL,
  `service_offering_id` binary(16) DEFAULT NULL,
  `stylist_id` binary(16) DEFAULT NULL,
  `salon_id` binary(16) DEFAULT NULL,
  `booking_id` binary(16) DEFAULT NULL,
  `order_id` binary(16) DEFAULT NULL,
  `rating` int DEFAULT '5',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `review_content` text COLLATE utf8mb4_unicode_ci,
  `media_gallery_urls` json DEFAULT NULL,
  `is_verified_purchase` tinyint(1) NOT NULL DEFAULT '1',
  `helpful_count` int NOT NULL DEFAULT '0',
  `unhelpful_count` int NOT NULL DEFAULT '0',
  `admin_reply_content` text COLLATE utf8mb4_unicode_ci,
  `admin_replied_by` binary(16) DEFAULT NULL,
  `admin_replied_at` datetime DEFAULT NULL,
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'APPROVED',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `sentiment_tag` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`review_id`),
  KEY `fk_reviews_user` (`user_id`),
  KEY `fk_reviews_product` (`product_id`),
  CONSTRAINT `fk_reviews_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`),
  CONSTRAINT `fk_reviews_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

