INSERT INTO `service_offerings` VALUES (0x46C1603CEE2D44798B49339830325414,NULL,'Cạo râu cổ điển Straight Razor',NULL,NULL,'Cạo râu bằng dao cổ điển, kem cạo râu hảo hạng, khăn nóng thư giãn cơ mặt. Trải nghiệm barber đích thực.',0.00,NULL,130000.00,40,45,5,'https://images.unsplash.com/photo-1503951914875-452162b0f3f1?w=500&auto=format&fit=crop',NULL,NULL,560,4.92,0,0,0,NULL,'JUNIOR',0,'ACTIVE',NULL,0,0,0x715147B571B44C1AB048842D85FE2D13,0x62EBD0BC948B40E69BDFDEED917B5F9A,'2026-10-12 01:58:41','2026-10-12 01:58:41'),(0x4763FBE1129E4081888BCFF42FA46B65,NULL,'Cắt tóc nam chuẩn BachBarber',NULL,NULL,'Cắt tóc theo phong cách hiện đại, tư vấn kiểu phù hợp khuôn mặt, gội đầu massage thư giãn sau cắt.',0.00,NULL,120000.00,45,45,5,'https://images.unsplash.com/photo-1598524374912-628cbcddbc1f?w=500&auto=format&fit=crop',NULL,NULL,2450,4.9,0,0,0,NULL,'JUNIOR',0,'ACTIVE',NULL,0,0,0x18AC3F01364243ACA9D8908B085849CD,0x03924BBDF27E4CB78204E551C4865923,'2026-10-12 01:58:41','2026-10-12 01:58:41'),(0x526B6DE492194A488B953AE67679E0C1,NULL,'Nhuộm tóc thời trang',NULL,NULL,'Nhuộm màu highlight, ombre, balayage với thuốc nhuộm cao cấp Wella/L\'Oreal. Tư vấn màu sắc cá nhân.',0.00,NULL,480000.00,150,45,5,'https://images.unsplash.com/photo-1519823551278-64ac92734fb1?w=500&auto=format&fit=crop',NULL,NULL,650,4.8,0,0,0,NULL,'JUNIOR',0,'ACTIVE',NULL,0,0,0x18AC3F01364243ACA9D8908B085849CD,0x03924BBDF27E4CB78204E551C4865923,'2026-10-12 01:58:41','2026-10-12 01:58:41'),(0x6F53151DFEE24D7EAF1C154EF8691342,NULL,'Uốn tóc Hàn Quốc',NULL,NULL,'Uốn xoăn nhẹ phong cách Hàn Quốc, tóc bồng bềnh tự nhiên không cứng. Bao gồm dưỡng ẩm sau uốn.',0.00,NULL,350000.00,120,45,5,'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?w=500&auto=format&fit=crop',NULL,NULL,780,4.85,0,0,0,NULL,'JUNIOR',0,'ACTIVE',NULL,0,0,0x18AC3F01364243ACA9D8908B085849CD,0x62EBD0BC948B40E69BDFDEED917B5F9A,'2026-10-12 01:58:41','2026-10-12 01:58:41'),(0x6F690432699A4505B639869BFC4DBE57,NULL,'Tỉa & tạo hình râu',NULL,NULL,'Tạo hình râu theo ý muốn, tỉa gọn, làm sạch đường viền. Bao gồm dưỡng beard oil sau tạo kiểu.',0.00,NULL,100000.00,30,45,5,'https://images.unsplash.com/photo-1621605815971-fbc98d665033?w=500&auto=format&fit=crop',NULL,NULL,380,4.87,0,0,0,NULL,'JUNIOR',0,'ACTIVE',NULL,0,0,0x715147B571B44C1AB048842D85FE2D13,0x28FD0D04DE55416E995A55CC85F41358,'2026-10-12 01:58:41','2026-10-12 01:58:41'),(0x8A2BDE63084748E5B8D216FC85535AA7,NULL,'Chăm sóc da mặt cơ bản',NULL,NULL,'Làm sạch sâu lỗ chân lông, đắp mặt nạ dưỡng ẩm, tẩy da chết nhẹ nhàng phù hợp da nam.',0.00,NULL,200000.00,75,45,5,'https://images.unsplash.com/photo-1570172619644-dfd03ed5d881?w=500&auto=format&fit=crop',NULL,NULL,420,4.75,0,0,0,NULL,'JUNIOR',0,'ACTIVE',NULL,0,0,0xC639B696434B4546BBBBDD05720F42B5,0x28FD0D04DE55416E995A55CC85F41358,'2026-10-12 01:58:41','2026-10-12 01:58:41'),(0xFB097FEA559C4066B599BB6F3FB78C7C,NULL,'Cắt Fade + Undercut',NULL,NULL,'Kỹ thuật fade (low/mid/high) kết hợp undercut tạo độ sắc nét tối đa, phù hợp phong cách street và Hàn Quốc.',0.00,NULL,180000.00,60,45,5,'https://images.unsplash.com/photo-1503951914875-452162b0f3f1?w=500&auto=format&fit=crop',NULL,NULL,1820,4.95,0,0,0,NULL,'JUNIOR',0,'ACTIVE',NULL,0,0,0x18AC3F01364243ACA9D8908B085849CD,0x03924BBDF27E4CB78204E551C4865923,'2026-10-12 01:58:41','2026-10-12 01:58:41'),(0xFEF35CE4FE3F4634A66DF64D33D77A35,NULL,'Combo Cắt + Gội + Massage VIP',NULL,NULL,'Gói phục vụ trọn gói cao cấp nhất: Cắt tóc, gội dưỡng sinh 30 phút, đắp mặt nạ và sấy tạo kiểu bằng sáp xịn.',0.00,NULL,150000.00,60,45,5,'https://images.unsplash.com/photo-1516975080661-46bfa33f93a1?w=500&auto=format&fit=crop',NULL,NULL,1350,4.88,0,0,0,NULL,'JUNIOR',0,'ACTIVE',NULL,0,0,0xC639B696434B4546BBBBDD05720F42B5,0x03924BBDF27E4CB78204E551C4865923,'2026-10-12 01:58:41','2026-10-18 04:20:37');
